	private static void verifyOptionalMarker(Path results, String childName, String witnessName,
			String scenario, boolean expected) throws IOException {
		Path child = results.resolve(childName);
		Path witness = results.resolve(witnessName);
		if (Files.exists(child) != expected || Files.exists(witness) != expected) {
			throw new AssertionError("commit marker presence does not match scenario " + scenario + ": " + childName);
		}
		if (expected) {
			assertBytesEqual(child, witness, childName);
			String boundary = childName.contains("commit-invoked")
					? "SailConnection.commit-entry" : "SailConnection.commit-returned";
			assertTextEquals(scenario + "\t" + boundary + "\n", child, childName);
		}
	}

	private static ObservedState observe(RepositoryConnection connection) throws Exception {
		Set<String> all = readStatements(connection, true);
		Set<String> explicit = readStatements(connection, false);
		Set<String> inferredOnly = new LinkedHashSet<>(all);
		inferredOnly.removeAll(explicit);
		Map<String, String> namespaces = new LinkedHashMap<>();
		try (RepositoryResult<Namespace> results = connection.getNamespaces()) {
			while (results.hasNext()) {
				Namespace namespace = results.next();
				if (namespaces.put(namespace.getPrefix(), namespace.getName()) != null) {
					throw new AssertionError("duplicate namespace prefix: " + namespace.getPrefix());
				}
			}
		}
		return new ObservedState(all, explicit, inferredOnly, namespaces);
	}

	private static Set<String> readStatements(RepositoryConnection connection, boolean includeInferred)
			throws Exception {
		Set<String> statements = new LinkedHashSet<>();
		try (RepositoryResult<Statement> results = connection.getStatements(null, null, null, includeInferred)) {
			while (results.hasNext()) {
				String statement = CrashPowerCutFixtures.canonicalStatement(results.next());
				if (!statements.add(statement)) {
					throw new AssertionError("public statement iteration returned a duplicate: " + statement);
				}
			}
		}
		return statements;
	}

	private static void publicIndexChecks(RepositoryConnection connection,
			CrashPowerCutFixtures.ExpectedState expected, String outcome) throws Exception {
		if (!connection.hasStatement(A_KEEP.getSubject(), null, null, true, GRAPH)) {
			throw new AssertionError("subject/context index lost the stable A statement");
		}
		if (!connection.hasStatement(null, PREDICATE, null, true, GRAPH)) {
			throw new AssertionError("predicate/context index lost the stable A statements");
		}
		if (!connection.hasStatement(null, null, A_KEEP.getObject(), true)) {
			throw new AssertionError("object index lost the stable A literal");
		}
		if (!connection.hasStatement(null, null, null, true, GRAPH)) {
			throw new AssertionError("context index lost the stable named graph");
		}
		if (!Objects.equals(expected.namespaces.get("crash"), connection.getNamespace("crash"))) {
			throw new AssertionError("public namespace lookup does not match the selected complete transaction state");
		}
		try (RepositoryResult<Statement> exact = connection.getStatements(A_KEEP.getSubject(), PREDICATE,
				A_KEEP.getObject(), true, GRAPH)) {
			if (!exact.hasNext() || !A_KEEP.equals(exact.next()) || exact.hasNext()) {
				throw new AssertionError("fully bound context lookup did not return exactly the stable A statement");
			}
		}
		boolean promotedExplicit = connection.hasStatement(A_PROMOTED.getSubject(), A_PROMOTED.getPredicate(),
				A_PROMOTED.getObject(), false, A_PROMOTED.getContext());
		boolean expectPromotion = expected.explicit.contains(CrashPowerCutFixtures.canonicalStatement(A_PROMOTED));
		if (promotedExplicit != expectPromotion) {
			throw new AssertionError("inferred-to-explicit promotion result mismatch: expected " + expectPromotion
					+ " but got " + promotedExplicit);
		}
		if (!connection.prepareBooleanQuery(QueryLanguage.SPARQL,
				"ASK { GRAPH <" + GRAPH.stringValue() + "> { <" + A_KEEP.getSubject().stringValue() + "> <"
						+ PREDICATE.stringValue() + "> \"kept in both generations\" } }").evaluate()) {
				throw new AssertionError("public SPARQL evaluation lost a stable A statement");
		}
		Statement firstGenerated = firstGeneratedStatement();
		boolean expectedFirstGenerated = expected.all().contains(CrashPowerCutFixtures.canonicalStatement(firstGenerated));
		boolean actualFirstGenerated = connection.hasStatement(firstGenerated.getSubject(), firstGenerated.getPredicate(),
				firstGenerated.getObject(), true, firstGenerated.getContext());
		if (actualFirstGenerated != expectedFirstGenerated) {
			throw new AssertionError("public exact lookup for B data does not match recovered " + outcome + " state");
		}
	}

	private static void assertBytesEqual(Path first, Path second, String label) throws IOException {
		if (!Files.isRegularFile(first) || !Files.isRegularFile(second)
				|| !java.util.Arrays.equals(Files.readAllBytes(first), Files.readAllBytes(second))) {
			throw new AssertionError(label + " is missing or differs from its independent witness copy");
		}
	}

	private static void assertTextEquals(String expected, Path actual, String label) throws IOException {
		String text = Files.readString(actual, StandardCharsets.UTF_8);
		if (!Objects.equals(expected, text)) {
			throw new AssertionError(label + " differs: expected bytes=" + expected.length() + " actual bytes="
					+ text.length());
		}
	}

	private static void writeForced(Path path, String value) throws IOException {
		byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
		try (FileChannel channel = FileChannel.open(path, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
			ByteBuffer buffer = ByteBuffer.wrap(bytes);
			while (buffer.hasRemaining()) {
				channel.write(buffer);
			}
			channel.force(true);
		}
		try (FileChannel directory = FileChannel.open(path.getParent(), StandardOpenOption.READ)) {
			directory.force(true);
		}
	}

	private record ObservedState(Set<String> all, Set<String> explicit, Set<String> inferredOnly,
			Map<String, String> namespaces) {
		boolean matches(CrashPowerCutFixtures.ExpectedState expected) {
			return all.equals(expected.all()) && explicit.equals(expected.explicit)
					&& inferredOnly.equals(expected.inferred) && namespaces.equals(expected.namespaces);
		}

		String digest() throws Exception {
			CrashPowerCutFixtures.ExpectedState state = new CrashPowerCutFixtures.ExpectedState();
			state.explicit.addAll(explicit);
			state.inferred.addAll(inferredOnly);
			state.namespaces.putAll(namespaces);
			return state.digest();
		}
	}
